node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Process the exchange
const now = new Date().toISOString();

// 1. Update the order with exchange details
db.prepare(\`
  UPDATE orders SET
    status = 'exchange_requested',
    exchange_items = ?,
    exchange_new_items = ?,
    exchange_payment_method_id = ?,
    exchange_price_difference = ?
  WHERE order_id = ?
\`).run(
  JSON.stringify([{ item_id: '3301828484', reason: 'size_exchange' }]),
  JSON.stringify([{ item_id: '7389318502' }]),
  'credit_card_9958253',
  -1.08,
  '#W7231611'
);

// 2. Update the order item status
db.prepare(\`
  UPDATE order_items SET
    item_status = 'exchange_requested',
    replacement_item_id = ?
  WHERE order_id = ? AND item_id = ?
\`).run('7389318502', '#W7231611', '3301828484');

// Verify the updates
const order = db.prepare('SELECT order_id, status, exchange_items, exchange_new_items, exchange_payment_method_id, exchange_price_difference FROM orders WHERE order_id = ?').get('#W7231611');
console.log('Updated order:', JSON.stringify(order, null, 2));

const item = db.prepare('SELECT oi_id, item_id, item_status, replacement_item_id FROM order_items WHERE order_id = ?').get('#W7231611');
console.log('Updated item:', JSON.stringify(item, null, 2));
"
